async function findMapPlace(){
 const q=mapQuery.trim();if(q.length<2){setNotice('พิมพ์ชื่อสถานที่อย่างน้อย 2 ตัวอักษร');return;}
 setMapSearching(true);
 try{const places=await searchMapPlaces(q);setMapPlaces(places);if(!places.length)setNotice('ไม่พบสถานที่จาก OpenStreetMap');}
 catch{setNotice('ค้นหาสถานที่ไม่ได้ในขณะนี้ — ยังสามารถกรอกพิกัดเองได้');}
 finally{setMapSearching(false);}
}
useEffect(()=>{function key(e:KeyboardEvent){if(exportRequest||!(e.ctrlKey||e.metaKey))return;const target=e.target as HTMLElement;if(target.closest('input,textarea,[contenteditable=true]'))return;const key=e.key.toLowerCase();if(key==='z'){e.preventDefault();if(e.shiftKey){if(future.length){setPast(p=>[...p,d]);setD(future[0]);setFuture(f=>f.slice(1));}}else if(past.length){setFuture(f=>[d,...f]);setD(past.at(-1)!);setPast(p=>p.slice(0,-1));}}if(key==='s'){e.preventDefault();download(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),'intersection.json');}}
window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);},[d,past,future,exportRequest]);
